/* 长文档：非中文语种显示英文译本（中文原文保留在 index.html 内） */
var DOC_EN = {
  rel: "\n<div class=\"vwrap\">\n  <div>\n    <div class=\"vbig\">Orion AI 2.4.2</div>\n    <div class=\"vinfo\">2026-11-24 · Desktop (Electron 35 / Windows x64)</div>\n  </div>\n  <span class=\"vtag\">v2.4.2</span>\n</div>\n<h4>2.4.2</h4>\n<ul>\n  <li>All system copy now exists in 7 languages: settings pane, model and permission menus, balance and unit price labels, work-mode step cards, diff cards, usage bar, trace view and empty states, plus every toast and error message. Switching applies immediately — no half-Chinese leftovers.</li>\n  <li>Message actions (read aloud, regenerate, copy), thinking state, stop chip, attachment chips and balance sync status are localized too.</li>\n  <li>Number formatting follows the language: 亿 / 万 in Chinese, M / K elsewhere.</li>\n</ul>\n<h4>2.4.1</h4>\n<ul>\n  <li>Speech is paid for once: each answer is synthesized once and stored as a local audio file keyed by text + voice; playing it again reads the local file with no API call and no tokens.</li>\n  <li>Survives restarts: the cache lives in the user data folder (tts), so reopening the app still reuses it.</li>\n  <li>Only the 40 most recent clips are kept; the oldest are pruned automatically.</li>\n</ul>\n<h4>2.4.0</h4>\n<ul>\n  <li>Change gate: before writing or editing a file in work mode, a diff card shows the target file and +/− line counts. Nothing touches disk until you press Apply; Cancel leaves everything as is, and no answer within 120s cancels.</li>\n  <li>Undo: every write takes a snapshot first, and each card offers Undo this step, restoring the file (newly created files are removed).</li>\n  <li>Auto-apply for the rest of a task, so you do not have to approve each write.</li>\n  <li>A usage bar at the bottom of work mode: steps, tool calls, tokens, elapsed time.</li>\n  <li>The permission pill left of the input shows the active level: read-only, workspace write, full access.</li>\n  <li>Fixed a packaging omission: workmode.js was missing from the installer, so the installed work mode was empty.</li>\n</ul>\n<h4>2.3.7</h4>\n<ul><li>Work mode became a workbench-style session: dialog and trace views, pending checklist, tool call cards, result blocks, with the composer and workspace switcher kept at the bottom.</li></ul>\n<h4>2.3.6</h4>\n<ul><li>Removed the task page; the UI is a plain chat again with the conversation title above the message area.</li><li>Added localization: Simplified Chinese, Traditional Chinese, English, Japanese, Korean, Russian, Arabic (RTL).</li></ul>\n<h4>2.3.5</h4>\n<ul><li>Dropped the native title bar for a slim custom one with floating window buttons.</li><li>Footer note is now “AI-generated content — please verify”; the repeated note inside answers is gone.</li><li>Web-search answers show “N pages found” above them, opening a source panel from the right.</li></ul>\n<h4>2.3.4</h4>\n<ul><li>Workspace label and path stay in sync live.</li><li>Conversation rows no longer stay highlighted after switching to tasks.</li></ul>\n<h4>2.3.3</h4>\n<ul><li>Sidebar has two entries — New work task / New chat — above the project workspace and recent chats.</li><li>Startup opens the chat page instead of jumping to tasks.</li><li>Greeting varies by time of day.</li></ul>\n<h4>2.3.2</h4>\n<ul><li>UI rebuild: only brand, new session and history on the left; Chat / Work tabs on top.</li><li>The Work tab is the task panel: goal, run, status filters, workspace and permission on top.</li><li>Brand is Orion AI; the preview badge is gone.</li><li>Models are named DeepSeek V3 / DeepSeek R1.</li><li>Tighter spacing, 1px separators, no rounded corners — closer to a desktop tool than a web template.</li></ul>\n<h4>2.3.1</h4>\n<ul><li>Real task panel: write a goal at the top, run it, then browse results filtered by all / running / done, and expand an entry to see every step.</li><li>Workspace and permission selectors moved next to the task environment.</li><li>New session is a pure chat page.</li></ul>\n<h4>2.3.0</h4>\n<ul><li>New workbench layout: left navigation and workspace list, brand area, workspace and mode selectors, rounded composer card.</li><li>Model can be switched next to the composer and stays in sync with settings.</li><li>Any local folder can be chosen as the workspace.</li><li>Mode selector (read-only / standard / full) maps to the agent permission level.</li><li>Fixed the blank window after installing 2.2.0.</li></ul>\n<h4>2.2.0</h4>\n<ul><li>Source split into modules: index.html, styles.css, core.js, ui.js, app.js.</li><li>Installer ships README, LICENSE, security notes and the full disclaimer.</li><li>Repository README is bilingual; build docs use domestic npm and Electron mirrors.</li></ul>\n<h4>2.1.0</h4>\n<ul><li>Work task became a local agent: it can run PowerShell, read/write workspace files, list directories, take screenshots, click, type, send hotkeys and launch programs, step by step until done.</li><li>Three permission levels enforced in the main process, not in the UI: read-only, workspace write (default), full access. Out-of-scope access and dangerous commands are rejected.</li><li>Live task cards for thinking, tool calls, results and errors; stop mid-run, clear finished tasks, expand full steps.</li><li>Workspace is jailed by absolute path; screenshots and input need full access.</li><li>Command timeouts, process-tree cleanup, output truncation, max 12 steps per task.</li><li>Fixed the missing preload that broke the agent after packaging.</li><li>Data moved to %APPDATA%\\Orion so reinstalling keeps chats, key and settings.</li></ul>\n<h4>2.0.0</h4>\n<ul><li>Own brand and visual language: hand-drawn constellation mark, new palette and wordmark, no third-party assets.</li><li>Added the work task entry point.</li><li>Settings gained Release notes and Terms pages, stating clearly that this is an unofficial client.</li><li>Kept everything else: attachments, OCR, voice input, read-aloud, web search, context retention.</li></ul>\n<h4>1.2.x</h4>\n<ul><li>Context retention switch: 6 / 12 / 24 turns or all, default 12.</li><li>Caps: 24,000 characters of history, 6,000 for attachments, 5,000 for search results.</li><li>Per-conversation caching for the same file or question; no double billing.</li><li>OCR, speech and search tokens count toward usage.</li></ul>\n<h4>1.0.0</h4>\n<ul><li>First installer: Electron client, NSIS installer, desktop and start-menu shortcuts.</li><li>Uploads, pasted images, OCR, speech recognition, TTS and web search wired to the real API.</li><li>Live balance and token estimate in the sidebar.</li></ul>\n<h4>How to update</h4>\n<p>Run the new installer over the old one. Chats, key and settings live in the data folder next to the app and survive the upgrade.</p>",
  terms: "\n<div class=\"vbig\">Terms of Use &amp; Privacy</div>\n<div class=\"vinfo\">Effective 2026-11-22 · applies to the Orion desktop client</div>\n<h4>1. Nature of the software</h4>\n<p>Orion is a personal, self-built local desktop client that only connects to the AI service endpoint you choose yourself. It has no affiliation, agency or partnership with DeepSeek or any related entity, does not represent their official position, and is not an official product.</p>\n<p>Third-party names and model identifiers appear only to describe the endpoints and models being called; all trademarks and names belong to their respective owners.</p>\n<h4>2. Account and cost</h4>\n<ul>\n  <li>You must register on the provider's platform and obtain an API key yourself, and you bear all charges for API usage.</li>\n  <li>The key is stored only in the local user data folder %APPDATA%\\Orion. It is never uploaded and never passes through any server run by the author.</li>\n  <li>Balance and token figures are estimates converted from the provider's API response; the provider's billing is authoritative.</li>\n</ul>\n<h4>3. Data handling</h4>\n<ul>\n  <li>Chats, work tasks and settings are stored locally by default and are not deleted by uninstalling.</li>\n  <li>Text, images and files you send are submitted to the provider you configured; follow their terms and privacy policy.</li>\n  <li>OCR, speech recognition and TTS upload the relevant content to the provider. Do not submit confidential, sensitive or personal data.</li>\n</ul>\n<h4>4. Acceptable use</h4>\n<ul>\n  <li>Do not use the software to create or spread illegal content or content that infringes the rights of others.</li>\n  <li>Do not resell API access, run proxy top-ups, or operate bulk accounts in breach of the provider's terms.</li>\n  <li>Do not remove or falsify branding to pass the software off as any official product.</li>\n</ul>\n<h4>5. Local operations and risk</h4>\n<ul>\n  <li>Work tasks can run commands, modify files, take screenshots and control mouse and keyboard on this machine. This is high-risk; by default only workspace writes and safe commands are allowed.</li>\n  <li>With full access, the model can run any PowerShell command, read and write files outside the workspace, launch programs and operate the desktop. You are responsible for all consequences, including overwritten data, uninstalled software and changed system settings.</li>\n  <li>Describe task goals precisely. For anything that deletes, moves or overwrites, ask the agent to explore read-only first and check paths before granting writes.</li>\n  <li>Never put API keys, passwords or identity documents into task commands or file contents.</li>\n  <li>The software does not collect or upload your commands and their output; these are sent to your configured model endpoint as context so it can decide the next step.</li>\n</ul>\n<h4>6. Disclaimer</h4>\n<p>The software is provided as is, without warranty of accuracy, completeness or fitness for any purpose of the model's output. Losses caused by API changes, network failures, insufficient balance or policy violations are borne by the user. Assess the legal and compliance requirements of your jurisdiction before use.</p>\n<h4>7. Changes</h4>\n<p>Functional or terms changes are noted in Release notes; continued use means you accept the updated terms.</p>",
};
var _docZh = null;
function applyDocs() {
  var rd = document.getElementById('relDoc');
  var td = document.getElementById('termDoc');
  if (!_docZh) _docZh = { rel: rd ? rd.innerHTML : '', terms: td ? td.innerHTML : '' };
  var zh = (LANG === 'zh' || LANG === 'zh-TW');
  if (rd) rd.innerHTML = zh ? _docZh.rel : DOC_EN.rel;
  if (td) td.innerHTML = zh ? _docZh.terms : DOC_EN.terms;
}

function t(key, vars) {
  var d = I18N[LANG] || I18N.zh;
  var s = d[key];
  if (s == null) s = I18N.zh[key];
  if (s == null) return key;
  if (vars) {
    s = s.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] == null ? m : String(vars[k]); });
  }
  return s;
}

function greetKey() {
  var h = new Date().getHours();
  if (h < 5) return 'hero.hi1';
  if (h < 9) return 'hero.hi2';
  if (h < 12) return 'hero.hi3';
  if (h < 14) return 'hero.hi4';
  if (h < 18) return 'hero.hi5';
  if (h < 23) return 'hero.hi6';
  return 'hero.hi1';
}

function applyLang(code) {
  LANG = I18N[code] ? code : 'zh';
  var el = document.documentElement;
  el.lang = LANG === 'zh' ? 'zh-CN' : (LANG === 'zh-TW' ? 'zh-Hant' : LANG);
  el.dir = LANG === 'ar' ? 'rtl' : 'ltr';
  if (typeof applyDocs === 'function') applyDocs();
  document.querySelectorAll('[data-i18n]').forEach(function (n) {
    n.textContent = t(n.getAttribute('data-i18n'));
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(function (n) {
    n.setAttribute('placeholder', t(n.getAttribute('data-i18n-ph')));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(function (n) {
    n.setAttribute('title', t(n.getAttribute('data-i18n-title')));
  });
  if (window.renderConvs) renderConvs();
  if (window.renderWsPill) renderWsPill();
  if (window.renderModePill) renderModePill();
  if (window.renderTasks) renderTasks();
  if (window.renderWorkList) renderWorkList();
  if (window.renderWork) renderWork();
  if (window.renderWorkView) renderWorkView();
  if (window.renderQuota) renderQuota();
  if (typeof renderChat === 'function') renderChat();
  if (window.renderTop) renderTop();
  if (window.syncHero) syncHero();
}

function syncHero() {
  var e = document.getElementById('heroSay');
  if (e) e.textContent = t(greetKey());
}
